export function calculateHaversineKm(lat1, lon1, lat2, lon2) {
  if (lat1 == null || lon1 == null || lat2 == null || lon2 == null) return null;
  const R = 6371; // Rayon de la Terre en km
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon / 2) * Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

/**
 * Recherche le poste source Enedis / Caparéseau le plus proche géographiquement
 * @param {number} lat Latitude du site
 * @param {number} lng Longitude du site
 * @returns {object|null} Poste source le plus proche avec distance réelle en km
 */
export function findClosestCapareseauSubstation(lat, lng) {
  if (lat == null || lng == null) return null;
  const latNum = parseFloat(lat);
  const lngNum = parseFloat(lng);
  if (isNaN(latNum) || isNaN(lngNum)) return null;

  let minD = Infinity;
  let best = null;

  for (let i = 0; i < CAPARESEAU_SUBSTATIONS.length; i++) {
    const s = CAPARESEAU_SUBSTATIONS[i];
    const d = calculateHaversineKm(latNum, lngNum, s.lat, s.lng);
    if (d !== null && d < minD) {
      minD = d;
      best = s;
    }
  }

  if (!best) return null;

  const distanceKm = Math.round(minD * 10) / 10;
  return {
    name: best.name,
    code: best.code || best.name.substring(0, 5).toUpperCase(),
    voltageLevel: best.voltage ? (best.voltage.includes('20') ? best.voltage : best.voltage + ' 20 kV') : 'HTA 20 kV',
    gestionnaire: 'Enedis',
    distanceKm: distanceKm,
    quotePartS3renr: best.quotePart,
    quotePartS3renrEur: best.quotePartEur,
    capaciteReserveeMw: best.capReserveeMw,
    resteAffecterMw: best.capMw,
    fileAttenteMw: best.fileAttenteMw,
    lat: best.lat,
    lng: best.lng,
    statutRaccordement: best.capMw > 0 ? ('Capacité résiduelle ' + best.capMw + ' MW') : 'Transfo sol libre - Dépôt PTF'
  };
}
